question.intro:
לפניך ממשק המחלקה Button המייצגת כפתור. לכפתור שלוש תכונות: המספר הרשום עליו num, גודל הכפתור size וצבע הכפתור color.
פעולה בונה שבונה כפתור שרשום עליו המספר num, בגודל 5 ובצבע "black":
public Button(int num)
פעולה בונה שבונה כפתור שרשום עליו המספר num, בגודל size ובצבע color:
public Button(int num, int size, String color)
פעולה שמחזירה את גודל הכפתור:
public int getSize()
פעולה שמגדילה את גודל הכפתור ב-x:
public void addToSize(int x)
פעולה שמחזירה true אם הכפתור other זהה בגודלו לכפתור הנוכחי, אחרת false:
public boolean isSameSize(Button other)

classes.code:
public class Button {
    private int num;
    private int size;
    private String color;

    public Button(int num, int size, String color) {
        this.num = num;
        this.size = size;
        this.color = color;
    }

    public int getSize() {
        return size;
    }

    public String toString() {
        return num + ", " + size + ", " + color;
    }
}

tasks.solution:
public Button(int num) {
    this.num = num;
    this.size = 5;
    this.color = "black";
}

public void addToSize(int x) {
    size = size + x;
}

public boolean isSameSize(Button other) {
    return size == other.getSize();
}

givenCode.code:
public static String check(Object got, Object expected) {
    String g = String.valueOf(got);
    String e = String.valueOf(expected);
    if (g.equals(e)) {
        return "נכון";
    }
    return "לא נכון — התקבל " + g + ", צריך להתקבל " + e;
}

exercise.mainCode:
Button b1 = new Button(7);
System.out.println("סעיף א, בדיקה 1: " + check(b1, "7, 5, black"));
System.out.println("סעיף א, בדיקה 2: " + check(b1.getSize(), 5));
Button b2 = new Button(3, 12, "red");
b2.addToSize(2);
System.out.println("סעיף ב, בדיקה 1: " + check(b2.getSize(), 14));
b1.addToSize(9);
System.out.println("סעיף ב, בדיקה 2: " + check(b1.getSize(), 14));
System.out.println("סעיף ג, בדיקה 1: " + check(b1.isSameSize(b2), true));
Button b3 = new Button(4, 12, "blue");
System.out.println("סעיף ג, בדיקה 2: " + check(b3.isSameSize(b2), false));
System.out.println("סעיף ג, בדיקה 3: " + check(new Button(5).isSameSize(new Button(6)), true));
System.out.println("סעיף ד: הפלט של קטע הפעולה מתחיל כאן");
// סעיף ד: קטע הפעולה מהשאלה — עקבו אחריו לפני ההרצה
Button a1 = new Button(1, 12, "red");
Button a2 = new Button(2, 12, "green");
Button a3 = new Button(3, 12, "blue");
Button a4 = new Button(4);
a1.addToSize(2);
a4.addToSize(9);
if (a1.isSameSize(a3))
    System.out.println("****");
if (a4.isSameSize(a1))
    System.out.println("$$$");
if (a2.isSameSize(a3))
    System.out.println("###");

